"""Independent slow reference implementation straight from the task text."""
import json
from fractions import Fraction

def trunc(v, d):
    if d == 0: return 0
    return (v >> (128 - d)) << (128 - d)

def fmt(v):
    g = [(v >> sh) & 0xffff for sh in range(112, -1, -16)]
    best = None
    i = 0
    while i < 8:
        if g[i] == 0:
            j = i
            while j < 8 and g[j] == 0: j += 1
            if j - i >= 2 and (best is None or j - i > best[1]): best = (i, j - i)
            i = j
        else: i += 1
    if best is None:
        return ':'.join('%x' % x for x in g)
    i, l = best
    left = ':'.join('%x' % x for x in g[:i])
    right = ':'.join('%x' % x for x in g[i + l:])
    if left and right: return left + '::' + right
    if left: return left + '::'
    if right: return '::' + right
    return '::'

def al(k, x):
    return k * ((x + k - 1) // k) if x > 0 else 0

def spec_stage(fib, b, e, root=False):
    """One stage's nodes in spec form (child indices not filled)."""
    if root:
        prefices = [0]
    else:
        s = set()
        for (net, L, h) in fib:
            if L > b: s.add(trunc(net, b))
        prefices = sorted(s)
    nodes = []
    for q in prefices:
        rules = []
        if root:
            for (net, L, h) in fib:
                if L == 0: rules.append((0, net, h))
        for (net, L, h) in fib:
            if b < L <= e and trunc(net, b) == q:
                rules.append((L, net, h))
        rules.sort()
        edges = []
        if e < 128:
            s = set()
            for (net, L, h) in fib:
                if L > b and trunc(net, b) == q and L > e:
                    s.add(trunc(net, e))
            edges = sorted(s)
        nodes.append({'prefix': fmt(q) + '/%d' % b, 'rules': [
            {'prefix': fmt(net) + '/%d' % L, 'hop': h} for (L, net, h) in rules],
            'edges': [{'prefix': fmt(x) + '/%d' % e} for x in edges]})
    return nodes

def spec_stage_cost(fib, b, e, root=False):
    nodes = spec_stage(fib, b, e, root)
    inner = 0
    for nd in nodes:
        t = 128
        for r in nd['rules']:
            L = int(r['prefix'].rsplit('/', 1)[1])
            t += 32 + al(8, L - b)
        t += len(nd['edges']) * (32 + al(8, e - b))
        inner += al(64, t)
    return inner

def spec_nodes(fib, cuts):
    S = len(cuts) - 1
    stages = []
    for i in range(S):
        b = cuts[i]; e = cuts[i + 1]
        st = {'nodes': spec_stage(fib, b, e, root=(i == 0))}
        stages.append(st)
    for i in range(S - 1):
        pos = {}
        for j, nd in enumerate(stages[i + 1]['nodes']):
            pos[nd['prefix'].rsplit('/', 1)[0]] = j
        for nd in stages[i]['nodes']:
            for edg in nd['edges']:
                edg['child'] = pos[edg['prefix'].rsplit('/', 1)[0]]
    used = []
    for i in range(S):
        b = cuts[i]; e = cuts[i + 1]
        u = 0
        for nd in stages[i]['nodes']:
            t = 128
            for r in nd['rules']:
                L = int(r['prefix'].rsplit('/', 1)[1])
                t += 32 + al(8, L - b)
            t += len(nd['edges']) * (32 + al(8, e - b))
            u += al(64, t)
        used.append(u)
    return stages, used

def spec_peak(used, caps):
    return max(Fraction(u, c) for u, c in zip(used, caps))

def ref_opt(fib, caps, max_stride):
    """Independent optimum via a full U table built from spec_stage_cost."""
    S = len(caps)
    Ut = {}
    for b in range(0, 128):
        for e in range(b + 1, min(128, b + max_stride) + 1):
            Ut[(b, e)] = spec_stage_cost(fib, b, e, root=(b == 0))
    dp = [[None] * 129 for _ in range(S + 1)]
    dp[0][0] = Fraction(0)
    for k in range(1, S + 1):
        for e in range(1, 129):
            best = None
            for b in range(max(0, e - max_stride), e):
                if dp[k - 1][b] is None: continue
                cand = max(dp[k - 1][b], Fraction(Ut[(b, e)], caps[k - 1]))
                if best is None or cand < best: best = cand
            dp[k][e] = best
    if dp[S][128] is None: return None
    return dp[S][128]

def lpm(fib, addr):
    bl = -1; bh = None
    for (net, L, h) in fib:
        if L > bl and ((addr >> (128 - L)) if L else 0) == ((net >> (128 - L)) if L else 0):
            bl = L; bh = h
    return (bh, bl)
