import json, random, subprocess, sys
sys.path.insert(0, '/app/tmp')
import ref
from fractions import Fraction

def run(lines):
    p = subprocess.run(['/app/submit/run'], input='\n'.join(lines)+'\n', text=True,
                       capture_output=True, timeout=600)
    assert p.returncode == 0, p.stderr
    out = p.stdout.splitlines()
    assert len(out) == len(lines), (len(out), len(lines))
    return [json.loads(x) for x in out]

def gen_fib(rng, n, style):
    fib = []; seen = set()
    while len(fib) < n:
        if style == 'random':
            L = rng.choice([0, 8, 16, 24, 32, 48, 64, 96, 112, 128, 20, 33, 127])
            net = (rng.getrandbits(L) << (128 - L)) if L else 0
        elif style == 'dense':
            L = rng.choice([0, 16, 32, 48, 64])
            net = ((rng.getrandbits(32) << 96) | (rng.getrandbits(L) << (128 - L) if L else 0))
            net &= ((1 << L) - 1) << (128 - L) if L else 0
        else:
            L = rng.choice([1, 2, 3, 4, 5, 6, 7, 8])
            net = rng.getrandbits(L) << (128 - L)
        if (net, L) in seen: continue
        seen.add((net, L))
        fib.append((net, L, rng.randrange(0, 65536)))
    return fib

def pfrac(f):
    return {'num': f.numerator, 'den': f.denominator}

def main():
    rng = random.Random(int(sys.argv[2]) if len(sys.argv) > 2 else 12345)
    ntest = int(sys.argv[1]) if len(sys.argv) > 1 else 40
    reqs = []; metas = []
    for t in range(ntest):
        S = rng.choice([4, 5, 6, 7, 8, 16])
        base = -(-128 // S)
        ms = rng.choice([base, base, base + 1, base + 2, min(32, base + 5), 32])
        ms = max(1, min(32, ms))
        caps = [rng.choice([500, 1000, 2000, 4096, 10000, 100000, 10**9]) for _ in range(S)]
        style = rng.choice(['random', 'dense', 'chain'])
        n = rng.choice([0, 1, 2, 3, 5, 10, 20, 40])
        fib = gen_fib(rng, n, style)
        req = {'op': 'compile',
               'fib': [{'prefix': ref.fmt(net) + '/%d' % L, 'hop': h} for (net, L, h) in fib],
               'capacities': caps, 'max_stride': ms}
        reqs.append(json.dumps(req))
        metas.append((req, fib, caps, ms))
    resps = run(reqs)
    for i, (req, fib, caps, ms) in enumerate(metas):
        r = resps[i]
        bp = ref.ref_opt(fib, caps, ms)
        if bp is None:
            assert r == {'status': 'infeasible'}, (i, r, bp)
            continue
        assert r.get('status') == 'ok', (i, r, bp)
        assert set(r.keys()) == {'status','capacities','max_stride','cuts','stages','used_bits','peak'}
        assert r['capacities'] == caps and r['max_stride'] == ms
        cuts = r['cuts']
        assert cuts[0] == 0 and cuts[-1] == 128 and len(cuts) == len(caps) + 1
        for j in range(len(cuts) - 1):
            assert cuts[j+1] > cuts[j] and cuts[j+1] - cuts[j] <= ms
        exp_stages, exp_used = ref.spec_nodes(fib, cuts)
        assert exp_used == r['used_bits'], (i, exp_used, r['used_bits'], cuts)
        assert json.dumps(exp_stages, sort_keys=True) == json.dumps(r['stages'], sort_keys=True), \
            (i, json.dumps(exp_stages)[:1500], json.dumps(r['stages'])[:1500])
        pk = ref.spec_peak(r['used_bits'], caps)
        assert pfrac(pk) == r['peak'], (i, pk, r['peak'])
        assert pk == bp, (i, 'NOT OPTIMAL', pk, bp, cuts, fib, caps, ms)
    print('compile optimality OK', ntest)

main()
